INSERT INTO carreras (id, codigo, nombre, descripcion, duracion_semestres, activa) VALUES (1, 'TL-AADM', 'Técnico Laboral en Auxiliar Administrativo', 'Forma auxiliares para apoyar procesos administrativos, gestión documental y atención al cliente.', 3, 1);
INSERT INTO carreras (id, codigo, nombre, descripcion, duracion_semestres, activa) VALUES (2, 'TL-ACF', 'Técnico Laboral en Auxiliar Contable y Financiero', 'Forma auxiliares en registro contable, facturación y apoyo a procesos financieros de pequeñas empresas.', 3, 1);
INSERT INTO carreras (id, codigo, nombre, descripcion, duracion_semestres, activa) VALUES (3, 'TL-PSW', 'Técnico Laboral en Programación de Software', 'Forma programadores junior en lógica de programación, bases de datos y desarrollo web.', 3, 1);
INSERT INTO carreras (id, codigo, nombre, descripcion, duracion_semestres, activa) VALUES (4, 'TL-API', 'Técnico Laboral en Atención Integral a la Primera Infancia', 'Forma agentes educativos para el cuidado, la educación inicial y el desarrollo de niños de 0 a 5 años.', 3, 1);
INSERT INTO carreras (id, codigo, nombre, descripcion, duracion_semestres, activa) VALUES (5, 'TL-SST', 'Técnico Laboral en Seguridad y Salud en el Trabajo', 'Forma auxiliares para apoyar el sistema de gestión de seguridad y salud en el trabajo de las empresas.', 3, 1);
